#!/bin/bash

#########################################
# Generic TypeScript Generator
#########################################

create_ts() {

    FILE="$1"

    create_file "$FILE" || return

    NAME=$(basename "$FILE")
    NAME="${NAME%.ts}"

cat > "$FILE" <<EOF
/**
 * ${NAME}
 * Generated by Cosmic Builder
 */

export {};
EOF

    echo "✅ $FILE"

    ((CREATED++))
    ((TYPESCRIPT++))
}

